981	/** The signed-in user's API token, if any (the deployed sandbox requires sign-in for actions). */
982	async function optionalToken(): Promise<string | null> {
983	  if (sandboxToken && sandboxToken.exp > Date.now()) return sandboxToken.token;
984	  try {
985	    const r = await fetch("/api/ns-token", { cache: "no-store" });
986	    const j = r.ok ? await r.json() : null;
987	    sandboxToken = { token: j?.token ?? null, exp: Date.now() + (j?.token ? 50 * 60_000 : 30_000) };
988	  } catch {
989	    sandboxToken = { token: null, exp: Date.now() + 30_000 };
990	  }
991	  return sandboxToken.token;
992	}
