994	export async function post<T>(path: string, body?: unknown): Promise<T> {
995	  const token = await optionalToken();
996	  const r = await fetch(`${API}${path}`, {
997	    method: "POST",
998	    headers: { "content-type": "application/json", ...(token ? { Authorization: `Bearer ${token}` } : {}) },
999	    body: body === undefined ? undefined : JSON.stringify(body),
1000	  });
1001	  if (r.status === 401) {
1002	    if (confirm("Sign in with GitHub to drive the live sandbox (it runs real models)?")) {
1003	      window.location.href = `/signin?callbackUrl=${encodeURIComponent(window.location.pathname)}`;
1004	    }
1005	    throw new Error("sign in required");
1006	  }
1007	  if (!r.ok) throw new Error(`${path}: ${r.status}`);
1008	  return r.json();
1009	}
1010	
1011	/** Poll an endpoint. Returns [data, error, reload]. */
1012	export function usePoll<T>(path: string | null, ms = 3000): [T | null, string | null, () => void] {
1013	  const [data, setData] = useState<T | null>(null);
1014	  const [error, setError] = useState<string | null>(null);
1015	  const [n, setN] = useState(0);
1016	  useEffect(() => {
1017	    if (!path) return;
1018	    let alive = true;
1019	    const load = () =>
1020	      get<T>(path)
1021	        .then((d) => {
1022	          if (alive) {
1023	            setData(d);
1024	            setError(null);
1025	          }
1026	        })
1027	        .catch((e) => alive && setError(String(e)));
1028	    load();
1029	    const t = setInterval(load, ms);
1030	    return () => {
1031	      alive = false;
1032	      clearInterval(t);
1033	    };
1034	  }, [path, ms, n]);
1035	  return [data, error, () => setN((x) => x + 1)];
1036	}
1037	
1038	export type StreamEvent = { type: string; ts: number; [k: string]: unknown };
1039	
1040	/** Subscribe to the Server-Sent-Events stream. */
1041	export function useStream(onEvent: (e: StreamEvent) => void): boolean {
1042	  const [connected, setConnected] = useState(false);
1043	  const handler = useRef(onEvent);
1044	  handler.current = onEvent;
1045	  useEffect(() => {
1046	    const es = new EventSource(`${API}/api/stream`);
1047	    es.onopen = () => setConnected(true);
1048	    es.onerror = () => setConnected(false);
1049	    es.onmessage = (m) => {
1050	      try {
1051	        handler.current(JSON.parse(m.data));
1052	      } catch {
1053	        /* ignore malformed */
1054	      }
1055	    };
1056	    return () => es.close();
1057	  }, []);
1058	  return connected;
1059	}
