1062	  `$${(v ?? 0).toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits })}`;
1063	
1064	export const short = (s: string | null | undefined, n = 10) => (s ? s.slice(0, n) : "—");
