1078	export const clockTime = (ts: number, offsetS = 0, seconds = true) =>
1079	  new Date((ts + offsetS) * 1000).toLocaleTimeString([], {
1080	    hour: "2-digit",
1081	    minute: "2-digit",
1082	    second: seconds ? "2-digit" : undefined,
1083	    hour12: false,
