  cost_usd: number;
  provenance: Provenance | null;
  nightshift_trace_id?: string | null;
};

export type ActionRow = {
  id: number;
  incident_id: string;
  ts: number;
  kind: string;
  mode: string;
  status: string;
  reason: string | null;
  params: Record<string, unknown>;
};

export type IncidentDetail = IncidentRow & {
  diagnosis: Diagnosis | null;
  verification: {
    replay?: { n: number; passed: number; rate: number; items: Record<string, unknown>[] };
    live_ok?: boolean;
    live_reasons?: string[];
  } | null;
  events: IncidentEvent[];
  actions: ActionRow[];
  postmortem: string;
};

export type Release = {
  id: string;
  title: string;
  description: string;
  tools: string[];
  max_steps: number;
  orders_api: string;
  provenance: Provenance | null;
};

export type State = {
  brain: string;
  local_time: string;
  local_time_simulated: boolean;
  local_offset_s: number;
  release: string;
  release_title: string;
  model: string;
  flags: Record<string, boolean>;
  outage_models: string[];
  traffic: { running: boolean; per_minute: number; attack_share: number };
  nightshift_enabled: boolean;
  open_incident: IncidentRow | null;
  totals: { n: number; loss: number; cost: number };
  budget: { available: boolean; spend?: number; max_budget?: number };
  signals: { name: string; description: string }[];
};

export async function get<T>(path: string): Promise<T> {
  const r = await fetch(`${API}${path}`, { cache: "no-store" });
  if (!r.ok) throw new Error(`${path}: ${r.status}`);
  return r.json();
}

let sandboxToken: { token: string | null; exp: number } | null = null;

/** The signed-in user's API token, if any (the deployed sandbox requires sign-in for actions). */
async function optionalToken(): Promise<string | null> {
  if (sandboxToken && sandboxToken.exp > Date.now()) return sandboxToken.token;
  try {
    const r = await fetch("/api/ns-token", { cache: "no-store" });
    const j = r.ok ? await r.json() : null;
    sandboxToken = { token: j?.token ?? null, exp: Date.now() + (j?.token ? 50 * 60_000 : 30_000) };
  } catch {
    sandboxToken = { token: null, exp: Date.now() + 30_000 };
  }
  return sandboxToken.token;
}

export async function post<T>(path: string, body?: unknown): Promise<T> {
  const token = await optionalToken();
  const r = await fetch(`${API}${path}`, {
    method: "POST",
    headers: { "content-type": "application/json", ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (r.status === 401) {
    if (confirm("Sign in with GitHub to drive the live sandbox (it runs real models)?")) {
      window.location.href = `/signin?callbackUrl=${encodeURIComponent(window.location.pathname)}`;
    }
    throw new Error("sign in required");
  }
  if (!r.ok) throw new Error(`${path}: ${r.status}`);
  return r.json();
}

/** Poll an endpoint. Returns [data, error, reload]. */
export function usePoll<T>(path: string | null, ms = 3000): [T | null, string | null, () => void] {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!path) return;
    let alive = true;
    const load = () =>
      get<T>(path)
        .then((d) => {
          if (alive) {
            setData(d);
            setError(null);
          }
        })
        .catch((e) => alive && setError(String(e)));
    load();
    const t = setInterval(load, ms);
    return () => {
      alive = false;
      clearInterval(t);
    };
  }, [path, ms, n]);
  return [data, error, () => setN((x) => x + 1)];
}

export type StreamEvent = { type: string; ts: number; [k: string]: unknown };

/** Subscribe to the Server-Sent-Events stream. */
export function useStream(onEvent: (e: StreamEvent) => void): boolean {
  const [connected, setConnected] = useState(false);
  const handler = useRef(onEvent);
  handler.current = onEvent;
  useEffect(() => {
    const es = new EventSource(`${API}/api/stream`);
    es.onopen = () => setConnected(true);
    es.onerror = () => setConnected(false);
    es.onmessage = (m) => {
      try {
        handler.current(JSON.parse(m.data));
      } catch {
        /* ignore malformed */
      }
    };
    return () => es.close();
  }, []);
  return connected;
}

export const money = (v: number | null | undefined, digits = 0) =>
  `$${(v ?? 0).toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits })}`;

export const short = (s: string | null | undefined, n = 10) => (s ? s.slice(0, n) : "—");

export const neatlogsTraceUrl = (traceId: string) =>
  `https://app.neatlogs.com/traces?search=${encodeURIComponent(traceId)}`;

export const OUTCOME_COLOR: Record<string, string> = {
  correct: "var(--ok)",
  escalated: "var(--info)",
  wrong_refund: "var(--alert)",
  missed_refund: "var(--amber)",
  failed: "var(--alert)",
};

/** Format a unix timestamp on the on-call clock (which may be pinned to a simulated local time). */
export const clockTime = (ts: number, offsetS = 0, seconds = true) =>
  new Date((ts + offsetS) * 1000).toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: seconds ? "2-digit" : undefined,
    hour12: false,
    timeZone: "UTC",
  });

