        <span className="text-[15px] font-medium text-fg">{s.caption}</span>
        {s.tag && <span className="ml-auto inline-flex items-center rounded-md border border-line px-2 py-1">{s.tag}</span>}
      </div>
      <Body d={d} />
    </div>
  );
}

