                  release <span className="text-fg">{state?.release ?? "—"}</span> “{state?.release_title ?? ""}”
                </span>
                <span>
                  model <span className="text-fg">{state?.model ?? "—"}</span>
                </span>
                <span>{state?.brain === "sim" ? "simulated brain (offline)" : "live models"}</span>
