function Idle({
  last,
  sum,
  onStart,
  busy,
}: {
  last: IncidentDetail | null;
  sum: { took: string | null; prevented: number | null; pending: number; contained: boolean } | null;
  onStart: () => void;
  busy: boolean;
}) {
