                  </span>
                )}
                {sum.prevented != null && (
                  <span>
                    · <strong className="font-semibold">{money(sum.prevented)}</strong> prevented
                  </span>
                )}
                {sum.pending > 0 && <span className="text-muted">· the permanent fix awaits your approval</span>}
              </div>
              <div className="mt-4 flex flex-wrap gap-3">
                <button
